INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(118887, 'ruRU', '', 'Что они делают с моим мальчиком?', 24330),
(118888, 'ruRU', '', 'Он уже должен был вернуться.', 24330),
(118889, 'ruRU', '', 'Будь проклят этот обман. Что они сделали с моим сыном?', 24330),
(118891, 'ruRU', '', 'Ох, Айлен... ты слишком юн, чтобы быть втянутым в это.', 24330),
(118893, 'ruRU', '', 'Где он? Где мой Айлен?', 24330),
(118925, 'ruRU', '', 'Какой безумец решил насытить это существо силой Ночного Колодца? Будь осторожен. Если эта мерзость была создана, чтобы защищать нижние уровни цитадели от захватчиков, она должна быть особенно смертоносна.', 24330),
(118926, 'ruRU', '', 'Разорви их плоть на части, мой питомец!', 24330),
(118927, 'ruRU', '', 'Я срежу твою плоть с костей!', 24330),
(118928, 'ruRU', '', 'Прими мою благодарность.', 24330),
(118929, 'ruRU', '', 'Теперь судьба моего народа покоится в руках чужаков... всех вас... чтобы спасти нас от ужасной сделки, заключённой нашей королевой.', 24330),
(118930, 'ruRU', '', 'Жрец, сюда! Мне нужна твоя помощь!', 24330),
(118931, 'ruRU', '', 'Shanar daloras! Понятия не имею, как возникла эта сущность, но сквозь неё течёт сама сущность Ночного Колодца.', 24330),
(118932, 'ruRU', '', 'Эта клетка может быть прочной, но помни, разум мурлока слаб и легко управляем!', 24330),
(118933, 'ruRU', '', 'Это знаменательный день, друзья мои. До прихода Легиона ни одному чужаку не позволялось входить в коридоры Цитадели Ночи на протяжении десяти тысяч лет.', 24330),
(118934, 'ruRU', '', 'Территория дворца прямо впереди. Ты обнаружишь, что она защищена даже сильнее, чем нижние уровни.', 24330),
(118935, 'ruRU', '', 'Клинок Заклинаний! Как только она будет побеждена, ничто не остановит нас от открытия дворцовых врат!', 24330),
(118936, 'ruRU', '', 'Наконец битва за освобождение Сурамара началась! Нашему сопротивлению больше не нужно прятаться в тенях!', 24330),
(118937, 'ruRU', '', 'Ночнорождённые стоят рядом с нашими союзниками, и древними, и новыми, чтобы отбросить Легион. Наши судьбы соединены, друзья мои! Спасая этот город от демонов, мы также спасаем весь Азерот! Tor ilisar''thera''nal!', 24330),
(118938, 'ruRU', '', 'Правление Великой Магистрикс оканчивается сегодня! Возьмите её башню, друзья мои! Свергните тирана и освободите мой народ!', 24330),
(118939, 'ruRU', '', 'Я пытался вырваться, но деревянные прутья слишком толстые.', 24330),
(118940, 'ruRU', '', 'Мы должны изгнать Легион, прежде чем их вмешательство высвободит ещё больше таких проявлений!', 24330),
(118941, 'ruRU', '', 'Мой народ заплатил страшную цену за сделку Элизанды с Легионом. Я ненавидел её за это! Но, возможно, магия, которую она дала тебе, может помочь одолеть наших врагов... и заслужить ей хоть немного прощения.', 24330),
(118942, 'ruRU', '', 'Удивлена найти меня живым, Алуриэль?', 24330),
(118943, 'ruRU', '', 'Этреус считал себя выше... ну, всех. Признаюсь, мне понравилось видеть его униженным.', 24330),
(118944, 'ruRU', '', 'Что я могу сказать? Он относился к своей работе серьёзно.', 24330),
(118945, 'ruRU', '', 'Алуриэль обучила бесчисленное множество Ночнорождённых искусству клинка. Она могла бы стать ценным союзником, но выбрала неверную сторону.', 24330),
(118946, 'ruRU', '', 'Скавн! Нет! Ты заплатишь за это страданиями!', 24330),
(118948, 'ruRU', '', 'Ты!', 24330),
(118949, 'ruRU', '', 'Мне следовало лично заняться твоим уничтожением, а не оставлять это Меландрусу. Когда я закончу с этими щенками, твоя кровь обагрит мой клинок!', 24330),
(118952, 'ruRU', '', 'Народ Сурамара в неоплатном долгу перед этими героями. Я буду стоять с ними до конца.', 24330),
(118982, 'ruRU', '', 'Матиас Шо держится в плену в Чертогах Затмения к югу.', 24330),
(118984, 'ruRU', '', 'Давай быстро проберёмся к Матиасу Шо.', 24330),
(118985, 'ruRU', '', 'Не отставай. Матиас Шо не далеко.', 24330),
(118986, 'ruRU', '', '$p. Сюда.', 24330),
(118987, 'ruRU', '', 'Нам нужно быстро добраться до Матиаса.', 24330),
(118988, 'ruRU', '', 'Нет времени на промедление, $p.', 24330),
(118989, 'ruRU', '', 'Он здесь.', 24330),
(118990, 'ruRU', '', 'Теперь уже не далеко.', 24330),
(118991, 'ruRU', '', 'Он прямо вниз по лестнице. Скорее, $p!', 24330),
(118993, 'ruRU', '', 'Шаг за шагом, день за днём.', 24330);
